void load_hc_unit_definitions(const std::string& initialization_data_file) {
  std::vector<HCUnit> hc_units;
  std::map<int, HCUnit> hc_units_by_id;
  std::set<std::string> hc_units_by_name;
  std::unordered_map<std::string, int> hc_units_by_name_and_id;

  std::ifstream file(initialization_data_file);
  if (!file.is_open()) {
    throw std::runtime_error("Failed to open initialization data file");
  }

  std::string line;
  while (std::getline(file, line)) {
    HCUnit unit;
    unit.parse(line);
    hc_units.push_back(unit);
    hc_units_by_id[unit.id] = unit;
    hc_units_by_name.insert(unit.name);
    hc_units_by_name_and_id[unit.name] = unit.id;
  }
}

void loadThermostatDefinitions(const std::string& initializationFilePath) {
  std::ifstream file(initializationFilePath);
  if (!file.is_open()) {
    std::cerr << "Error: Unable to open initialization file" << std::endl;
    return false;
  }
  std::string line;
  while (std::getline(file, line)) {
    ThermostatDefinition thermostatDefinition;
    if (!parseThermostatDefinition(line, thermostatDefinition)) {
      std::cerr << "Error: Invalid thermostat definition" << std::endl;
      return false;
    }
    if (!validateThermostatDefinition(thermostatDefinition)) {
      std::cerr << "Error: Invalid thermostat definition" << std::endl;
      return false;
    }
    storeThermostatDefinition(thermostatDefinition);
  }
  file.close();
  return true;
}

bool validateThermostatDefinition(const ThermostatDefinition& thermostatDefinition) {
  // Check if the identifier is unique
  if (isIdentifierUnique(thermostatDefinition.identifier)) {
    // Check if the floor and quadrant are within valid ranges
    if (isFloorInRange(thermostatDefinition.floor) && isQuadrantInRange(thermostatDefinition.quadrant)) {
      // Check if the temperature range is within acceptable limits
      if (isTemperatureRangeValid(thermostatDefinition.temperatureRange)) {
        return true;
      }
    }
  }
  return false;
}

void storeThermostatDefinition(const ThermostatDefinition& thermostatDefinition) {
  // Check if the identifier is unique
  if (!isIdentifierUnique(thermostatDefinition.identifier)) {
    std::cerr << "Error: Identifier is not unique" << std::endl;
    return;
  }

  // Check if the floor and quadrant are within valid ranges
  if (!isFloorInRange(thermostatDefinition.floor) || !isQuadrantInRange(thermostatDefinition.quadrant)) {
    std::cerr << "Error: Floor or quadrant is out of range" << std::endl;
    return;
  }

  // Check if the temperature range is within acceptable limits
  if (!isTemperatureRangeValid(thermostatDefinition.temperatureRange)) {
    std::cerr << "Error: Temperature range is out of acceptable limits" << std::endl;
    return;
  }

  // Store the thermostat definition in the THEMAS system's database
  storeThermostatDefinition(thermostatDefinition);
}

